import {
    BadRequestException, ConflictException, Controller, ForbiddenException, Get,
    Module, NotFoundException, Param, UnauthorizedException,
} from "@nestjs/common"

@Controller("errors")
class ErrorsController {
    @Get(":type")
    throwError(@Param("type") type: string) {
        switch (type) {
            case "400": throw new BadRequestException("Noto'g'ri ma'lumot")
            case "401": throw new UnauthorizedException("Tizimga kiring")
            case "403": throw new ForbiddenException("Ruxsat yo'q")
            case "404": throw new NotFoundException("Topilmadi")
            case "409": throw new ConflictException("Bu email band")
            default: return "xato yo'q"
        }
    }
}

@Module({ controllers: [ErrorsController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    for (const code of ["400", "401", "403", "404", "409", "ok"]) {
        await http.get(`/errors/${code}`)
    }
    await http.close()
}
main()

