import { Controller, Get, HttpException, HttpStatus, Module, Param } from "@nestjs/common"

class OutOfStockException extends HttpException {
    constructor(product: string, available: number) {
        super(
            { error: "OUT_OF_STOCK", message: `${product} omborda yetarli emas`, available },
            HttpStatus.CONFLICT,
        )
    }
}

@Controller("cart")
class CartController {
    private stock: Record<string, number> = { noutbuk: 2 }

    @Get("add/:product/:qty")
    add(@Param("product") product: string, @Param("qty") qty: string) {
        const available = this.stock[product] ?? 0
        if (Number(qty) > available) throw new OutOfStockException(product, available)
        return { added: product, qty: Number(qty) }
    }
}

@Module({ controllers: [CartController] })
class AppModule {}

async function main() {
    const http = await testApp(AppModule)
    await http.get("/cart/add/noutbuk/1")
    await http.get("/cart/add/noutbuk/5")
    await http.close()
}
main()

