import { ArgumentsHost, Catch, Controller, ExceptionFilter, ForbiddenException, Get, HttpException, Module, UseFilters } from "@nestjs/common"
import type { Request, Response } from "express"

@Catch(HttpException)
class NegotiatingFilter implements ExceptionFilter {
    catch(e: HttpException, host: ArgumentsHost) {
        const req = host.switchToHttp().getRequest<Request>(), res = host.switchToHttp().getResponse<Response>()
        if (req.accepts(["json", "text"]) === "text") res.status(e.getStatus()).type("text").send(`Xato ${e.getStatus()}: ${e.message}`)
        else res.status(e.getStatus()).json({ status: e.getStatus(), message: e.message })
    }
}

