import { ArgumentsHost, BadRequestException, Catch, Controller, Get, HttpException, Injectable, Module } from "@nestjs/common"
import { APP_FILTER, BaseExceptionFilter } from "@nestjs/core"

@Injectable() class ErrorTracker { sent: string[] = []; capture(e: Error) { this.sent.push(e.message) } }

@Catch()
@Injectable()
class TrackingFilter extends BaseExceptionFilter {
    constructor(private readonly tracker: ErrorTracker) { super() }
    catch(e: unknown, host: ArgumentsHost) {
        const status = e instanceof HttpException ? e.getStatus() : 500
        if (status >= 500) this.tracker.capture(e as Error)   // 4xx — mijoz xatosi, yuborilmaydi
        super.catch(e, host)
    }
}

