import { ArgumentsHost, Catch, Controller, ExceptionFilter, Get, Module } from "@nestjs/common"

const makeFilter = (env: string) => {
    @Catch()
    class EnvAwareFilter implements ExceptionFilter {
        catch(e: Error, host: ArgumentsHost) {
            const body: Record<string, unknown> = { status: 500, message: "Ichki xato" }
            if (env !== "production") { body.detail = e.message; body.stackTop = e.stack?.split("\n")[0] }
            host.switchToHttp().getResponse().status(500).json(body)
        }
    }
    return EnvAwareFilter
}

