@Catch(HttpException) class NegotiateFilter implements ExceptionFilter {
    catch(e: HttpException, h: ArgumentsHost) {
        const req = h.switchToHttp().getRequest<Request>(), res = h.switchToHttp().getResponse<Response>()
        res.status(e.getStatus())
        req.accepts(["json", "text"]) === "text" ? res.type("text").send(`Xato: ${e.message}`) : res.json({ error: e.message })
    }
}
